/**
 * v2 round-trip stability test.
 *
 * Principle 3 (design lock): serialize(parse(source)) must be byte-for-byte
 * identical to serialize(parse(serialize(parse(source)))).
 */
import { describe, it, expect } from 'vitest';
import { parseTable }     from '../src/parser';
import { serializeTable } from '../src/serializer';

// ── Test fixtures ─────────────────────────────────────────────────────────────

const FIXTURES = [
	{
		name: 'minimal table',
		source: `---
version: 2
columns:
  - id: c_000000
    name: A
rows:
  - id: r_000000
    cells:
      c_000000: hello
---
<!-- Generated by Rich Table. Do not edit below — data source is the YAML front-matter above. -->
| A     |
| ----- |
| hello |`,
	},
	{
		name: 'table with styles, merges, filter, sort, aggregate, footer',
		source: `---
version: 2
columns:
  - id: c_000000
    name: 功能
    width: 101
  - id: c_000001
    name: 状态
    type: task-status
    width: 112
    filter:
      - done
rows:
  - id: r_000000
    cells:
      c_000000: 编辑单元格
      c_000001: done
  - id: r_000001
    height: 56
    cells:
      c_000000: 双链补全
      c_000001: done
merges:
  - anchor: r_000000.c_000001
    end: r_000001.c_000001
styles:
  - target: header
    bg: "#e8f0fe"
    bold: true
  - target: r_000000.c_000000
    bold: true
    align: right
footer: 测试
sort:
  colId: c_000000
  dir: asc
aggregate:
  - count
---
<!-- Generated by Rich Table. Do not edit below — data source is the YAML front-matter above. -->
| 功能       | 状态 |
| ---------- | ---- |
| 编辑单元格 | done |
| 双链补全   |      |`,
	},
	{
		name: 'hidden row and column',
		source: `---
version: 2
columns:
  - id: c_000000
    name: A
  - id: c_000001
    name: B
    hidden: true
rows:
  - id: r_000000
    cells:
      c_000000: visible
  - id: r_000001
    hidden: true
    cells:
      c_000000: hidden
---
<!-- Generated by Rich Table. Do not edit below — data source is the YAML front-matter above. -->
| A       |
| ------- |
| visible |`,
	},
	{
		name: 'table with title and locked',
		source: `---
version: 2
title: My Table
columns:
  - id: c_000000
    name: Col
rows:
  - id: r_000000
    cells:
      c_000000: value
locked: true
---
<!-- Generated by Rich Table. Do not edit below — data source is the YAML front-matter above. -->
| Col   |
| ----- |
| value |`,
	},
	{
		name: 'table with status bar mode and scroll width',
		source: `---
version: 2
columns:
  - id: c_000000
    name: A
rows:
  - id: r_000000
    cells:
      c_000000: hello
statusBarMode: hover
statusBarScrollWidth: 150
---
<!-- Generated by Rich Table. Do not edit below — data source is the YAML front-matter above. -->
| A     |
| ----- |
| hello |`,
	},
];

// ── Round-trip assertions ─────────────────────────────────────────────────────

describe('v2 round-trip stability', () => {
	for (const { name, source } of FIXTURES) {
		it(name, () => {
			const model1      = parseTable(source);
			const serialized1 = serializeTable(model1);
			const model2      = parseTable(serialized1);
			const serialized2 = serializeTable(model2);

			expect(serialized1).toBe(serialized2);
		});
	}
});

describe('align survives parse/serialize', () => {
	it('a style rule\'s align field is actually parsed and re-emitted, not just consistently dropped', () => {
		const model = parseTable(FIXTURES[1]!.source);
		expect(model.styles.find(s => s.target === 'r_000000.c_000000')?.align).toBe('right');
		expect(serializeTable(model)).toContain('align: right');
	});
});

describe('pipe-table mirror removal (backward compatibility)', () => {
	it('serializeTable no longer writes a pipe table below the front-matter', () => {
		const model = parseTable(FIXTURES[1]!.source);
		const out = serializeTable(model);
		expect(out).not.toContain('Generated by Rich Table');
		expect(out.split('\n').filter(l => l === '---')).toHaveLength(2);
		expect(out.trim().endsWith('---')).toBe(true);
	});

	it('an old note that still has a mirror below the front-matter parses identically to one without it', () => {
		const withMirror = FIXTURES[1]!.source;
		const withoutMirror = withMirror.slice(0, withMirror.indexOf('\n<!-- Generated'));
		expect(parseTable(withMirror)).toEqual(parseTable(withoutMirror));
	});
});

describe('views round-trip (serializeTable → parseTable)', () => {
	// Built directly (not as a hand-written YAML fixture, unlike FIXTURES above)
	// since matching stringifyYaml's exact key order/quoting byte-for-byte by
	// hand would be fragile — this instead checks the semantic round-trip a
	// real write-back/reload cycle depends on.
	it('preserves a kanban view and which one is active', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'Status', type: 'task-status' }],
			rows: [{ id: 'r_0', cells: { c_0: 'done' } }],
			merges: [],
			styles: [],
			views: [{ id: 'v_0', name: 'Kanban (Status)', type: 'kanban' as const, kanban: { groupByColId: 'c_0' } }],
			activeViewId: 'v_0',
		};

		const reparsed = parseTable(serializeTable(model));
		expect(reparsed.views).toEqual(model.views);
		expect(reparsed.activeViewId).toBe('v_0');

		// Second round trip must be stable (Principle 3).
		expect(serializeTable(reparsed)).toBe(serializeTable(parseTable(serializeTable(reparsed))));
	});

	it('preserves a calendar view and which one is active', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'Due', type: 'date' }],
			rows: [{ id: 'r_0', cells: { c_0: '2026-07-01' } }],
			merges: [],
			styles: [],
			views: [{ id: 'v_0', name: 'Calendar (Due)', type: 'calendar' as const, calendar: { dateColId: 'c_0' } }],
			activeViewId: 'v_0',
		};

		const reparsed = parseTable(serializeTable(model));
		expect(reparsed.views).toEqual(model.views);
		expect(reparsed.activeViewId).toBe('v_0');

		// Second round trip must be stable (Principle 3).
		expect(serializeTable(reparsed)).toBe(serializeTable(parseTable(serializeTable(reparsed))));
	});

	it('a table with no views field parses/serializes exactly as before this feature existed', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'A' }],
			rows: [{ id: 'r_0', cells: { c_0: 'x' } }],
			merges: [],
			styles: [],
		};
		const out = serializeTable(model);
		expect(out).not.toContain('views:');
		expect(out).not.toContain('activeViewId:');
	});

	it('drops an activeViewId that does not match any views[] entry, rather than persisting a dangling reference', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'A' }],
			rows: [{ id: 'r_0', cells: { c_0: 'x' } }],
			merges: [],
			styles: [],
			views: [{ id: 'v_0', name: 'K', type: 'kanban' as const, kanban: { groupByColId: 'c_0' } }],
			activeViewId: 'v_does_not_exist',
		};
		const reparsed = parseTable(serializeTable(model));
		expect(reparsed.activeViewId).toBeUndefined();
	});
});

describe('statusBarMode / statusBarScrollWidth', () => {
	it('parses an explicit hover mode and scroll width', () => {
		const model = parseTable(`---
version: 2
columns:
  - id: c_0
    name: A
rows:
  - id: r_0
    cells:
      c_0: x
statusBarMode: hover
statusBarScrollWidth: 150
---
`);
		expect(model.statusBarMode).toBe('hover');
		expect(model.statusBarScrollWidth).toBe(150);
	});

	it('leaves both fields undefined when absent — the model itself does not bake in the "pinned" default', () => {
		const model = parseTable(`---
version: 2
columns:
  - id: c_0
    name: A
rows:
  - id: r_0
    cells:
      c_0: x
---
`);
		expect(model.statusBarMode).toBeUndefined();
		expect(model.statusBarScrollWidth).toBeUndefined();
	});

	it('a table with neither field parses/serializes exactly as before this feature existed', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'A' }],
			rows: [{ id: 'r_0', cells: { c_0: 'x' } }],
			merges: [],
			styles: [],
		};
		const out = serializeTable(model);
		expect(out).not.toContain('statusBarMode:');
		expect(out).not.toContain('statusBarScrollWidth:');
	});

	it('round-trips an explicitly set pinned mode (same as the default, but still written once explicit)', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'A' }],
			rows: [{ id: 'r_0', cells: { c_0: 'x' } }],
			merges: [],
			styles: [],
			statusBarMode: 'pinned' as const,
			statusBarScrollWidth: 200,
		};
		const reparsed = parseTable(serializeTable(model));
		expect(reparsed.statusBarMode).toBe('pinned');
		expect(reparsed.statusBarScrollWidth).toBe(200);
	});

	it('rejects a non-positive or non-finite scroll width the same way viewWidth does', () => {
		const model = parseTable(`---
version: 2
columns:
  - id: c_0
    name: A
rows:
  - id: r_0
    cells:
      c_0: x
statusBarScrollWidth: -5
---
`);
		expect(model.statusBarScrollWidth).toBeUndefined();
	});
});

describe('xlsxSource round-trip', () => {
	it('parses path and sheet from front-matter', () => {
		const model = parseTable(`---
version: 2
columns: []
rows: []
xlsxSource:
  path: data/budget.xlsx
  sheet: Q1
---
`);
		expect(model.xlsxSource).toEqual({ path: 'data/budget.xlsx', sheet: 'Q1' });
	});

	it('parses path with no sheet (whole-workbook reference)', () => {
		const model = parseTable(`---
version: 2
columns: []
rows: []
xlsxSource:
  path: data/budget.xlsx
---
`);
		expect(model.xlsxSource).toEqual({ path: 'data/budget.xlsx' });
	});

	it('ignores an xlsxSource with no path at all rather than throwing', () => {
		const model = parseTable(`---
version: 2
columns: []
rows: []
xlsxSource:
  sheet: Q1
---
`);
		expect(model.xlsxSource).toBeUndefined();
	});

	it('ignores an xlsxSource with an empty-string path', () => {
		const model = parseTable(`---
version: 2
columns: []
rows: []
xlsxSource:
  path: ""
  sheet: Q1
---
`);
		expect(model.xlsxSource).toBeUndefined();
	});

	it('leaves xlsxSource undefined when absent, and omits the field on serialize', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'A' }],
			rows: [{ id: 'r_0', cells: { c_0: 'x' } }],
			merges: [],
			styles: [],
		};
		const out = serializeTable(model);
		expect(out).not.toContain('xlsxSource:');
		expect(parseTable(out).xlsxSource).toBeUndefined();
	});

	it('round-trips through serializeTable → parseTable unchanged', () => {
		const model = {
			version: 2 as const,
			columns: [{ id: 'c_0', name: 'A' }],
			rows: [{ id: 'r_0', cells: { c_0: 'x' } }],
			merges: [],
			styles: [],
			xlsxSource: { path: 'reports/2026.xlsx', sheet: '统计' },
		};
		const reparsed = parseTable(serializeTable(model));
		expect(reparsed.xlsxSource).toEqual({ path: 'reports/2026.xlsx', sheet: '统计' });
	});

	it('omits the dead columns:/rows: fields entirely when xlsxSource is set — they are never real data', () => {
		const model = {
			version: 2 as const,
			columns: [],
			rows: [],
			merges: [],
			styles: [],
			xlsxSource: { path: 'reports/2026.xlsx' },
		};
		const out = serializeTable(model);
		expect(out).not.toContain('columns:');
		expect(out).not.toContain('rows:');
	});

	it('still writes columns:/rows: as usual for a table with no xlsxSource, even when empty (a real emptied-out sheet)', () => {
		const model = {
			version: 2 as const,
			columns: [],
			rows: [],
			merges: [],
			styles: [],
		};
		const out = serializeTable(model);
		expect(out).toContain('columns:');
		expect(out).toContain('rows:');
	});
});

describe('tasks table round-trip', () => {
	const SOURCE = `---
version: 2
tasks:
  query: |
    not done
    tags include #question
    sort by created
columns:
  - id: c_status
    name: Status
    width: 36
    field: status
  - id: c_body
    name: Task
    field: body
---
`;

	it('reads the query, kept as written, and the field of each column', () => {
		const m = parseTable(SOURCE);
		expect(m.tasks).toEqual({ query: 'not done\ntags include #question\nsort by created\n' });
		expect(m.columns.map(c => c.field)).toEqual(['status', 'body']);
		expect(m.columns[0]).toMatchObject({ id: 'c_status', name: 'Status', width: 36, field: 'status' });
	});

	it('writes the query and the columns, and never the rows', () => {
		const m = parseTable(SOURCE);
		m.rows = [{ id: 'r_1', cells: { c_body: 'a task that was found' } }];
		const out = serializeTable(m);
		expect(out).not.toContain('rows:');
		expect(out).not.toContain('a task that was found');
		expect(out).toContain('field: status');
		expect(out).toContain('tags include #question');
		expect(parseTable(out).tasks).toEqual(m.tasks);
	});

	it('is stable: writing what was read changes nothing', () => {
		const once = serializeTable(parseTable(SOURCE));
		expect(serializeTable(parseTable(once))).toBe(once);
	});

	it('accepts an empty query, which finds every task', () => {
		expect(parseTable('---\nversion: 2\ntasks:\n  query: ""\ncolumns: []\n---\n').tasks).toEqual({ query: '' });
	});

	it('ignores a tasks entry without a query rather than throwing', () => {
		expect(parseTable('---\nversion: 2\ntasks: {}\ncolumns: []\nrows: []\n---\n').tasks).toBeUndefined();
		expect(parseTable('---\nversion: 2\ntasks: yes\ncolumns: []\nrows: []\n---\n').tasks).toBeUndefined();
	});

	it('ignores a field that is not text, and an empty one', () => {
		const m = parseTable('---\nversion: 2\ncolumns:\n  - { id: c_a, name: A, field: 3 }\n  - { id: c_b, name: B, field: "" }\nrows: []\n---\n');
		expect(m.columns.map(c => c.field)).toEqual([undefined, undefined]);
	});

	it('leaves a table without tasks exactly as it was: columns, then rows, no tasks key', () => {
		const out = serializeTable(parseTable('---\nversion: 2\ncolumns:\n  - { id: c_a, name: A }\nrows:\n  - { id: r_1, cells: { c_a: x } }\n---\n'));
		expect(out).not.toContain('tasks');
		expect(out.indexOf('columns:')).toBeLessThan(out.indexOf('rows:'));
	});
});
